   const n=needs[j]==='drink'?3:needs[j]==='position'?3:3;
   for(let i=0;i<n;i++) await page.locator('[data-choice="0"]').click();
 }
 if(await page.locator('#progressText').innerText()!=='6 / 6') throw new Error('rounds failed: '+await page.locator('#progressText').innerText());
 await page.locator('#finishBtn').click();
